import os
from builder_base import output_dir, head_content, header_html, footer_html

page_content = f"""
{head_content}
{header_html}

<main class="flex-grow flex flex-col md:flex-row h-[calc(100vh-80px)] overflow-hidden">
    <!-- Left Panel: Search & Results -->
    <div class="w-full md:w-1/3 lg:w-1/4 bg-white flex flex-col h-full z-10 shadow-xl overflow-hidden shrink-0">
        <!-- Search Controls -->
        <div class="p-4 border-b border-brand-forest/10">
            <!-- Order Type Toggle -->
            <div class="flex p-1 bg-brand-light rounded-full mb-4">
                <button id="btn-pickup" class="flex-1 py-1.5 px-4 rounded-full bg-white shadow-sm font-bold text-brand-forest text-sm transition-all toggle-type">Pickup</button>
                <button id="btn-delivery" class="flex-1 py-1.5 px-4 rounded-full text-brand-forest/60 font-bold text-sm hover:text-brand-forest transition-all toggle-type">Delivery</button>
            </div>

            <div class="relative flex items-center gap-2">
                <div class="relative flex-1">
                    <input type="text" id="store-search" placeholder="Find a store" class="w-full pl-10 pr-4 py-2 border-b-2 border-brand-forest/30 focus:border-brand-green bg-transparent outline-none transition-colors placeholder:text-brand-forest/40 font-medium">
                    <i data-lucide="search" class="w-5 h-5 absolute left-2 top-1/2 -translate-y-1/2 text-brand-forest/40"></i>
                </div>
                <button id="btn-filter" class="p-2 text-brand-forest hover:bg-brand-light rounded-full transition-colors relative">
                    <i data-lucide="sliders-horizontal" class="w-5 h-5"></i>
                </button>
            </div>

            <!-- Filter Panel (Hidden by default) -->
            <div id="filter-panel" class="hidden mt-4 pt-4 border-t border-brand-forest/10 text-sm">
                <h4 class="font-bold text-brand-forest mb-2">Amenities</h4>
                <label class="flex items-center gap-2 mb-2 cursor-pointer">
                    <input type="checkbox" class="rounded text-brand-green focus:ring-brand-green accent-brand-green">
                    <span>Drive-Thru</span>
                </label>
                <label class="flex items-center gap-2 mb-2 cursor-pointer">
                    <input type="checkbox" class="rounded text-brand-green focus:ring-brand-green accent-brand-green">
                    <span>Mobile Order and Pay</span>
                </label>
                <label class="flex items-center gap-2 mb-2 cursor-pointer">
                    <input type="checkbox" class="rounded text-brand-green focus:ring-brand-green accent-brand-green">
                    <span>In-Store Seating</span>
                </label>
            </div>
        </div>

        <!-- Search Results List -->
        <div class="flex-1 overflow-y-auto p-4 hide-scroll" id="results-list">
            <p class="text-sm text-brand-forest/60 mb-4 font-medium" id="search-message">Zoom in to see stores in this area.</p>

            <div class="store-result p-4 border border-brand-forest/10 rounded-2xl mb-4 hover:border-brand-green hover:shadow-md transition-all cursor-pointer bg-white group">
                <h3 class="font-bold text-brand-forest mb-1">Downtown Center</h3>
                <p class="text-sm text-brand-forest/70 mb-1">123 Main St, Suite 100</p>
                <p class="text-xs text-brand-forest/50 mb-3">Open until 9:00 PM</p>
                <div class="flex gap-2">
                    <span class="text-xs bg-brand-light text-brand-forest px-2 py-1 rounded-md font-medium">Drive-Thru</span>
                    <span class="text-xs bg-brand-light text-brand-forest px-2 py-1 rounded-md font-medium">Mobile Order</span>
                </div>
            </div>

            <div class="store-result p-4 border border-brand-forest/10 rounded-2xl mb-4 hover:border-brand-green hover:shadow-md transition-all cursor-pointer bg-white group">
                <h3 class="font-bold text-brand-forest mb-1">Uptown Square</h3>
                <p class="text-sm text-brand-forest/70 mb-1">456 Broad Ave</p>
                <p class="text-xs text-brand-forest/50 mb-3">Open until 8:00 PM</p>
                <div class="flex gap-2">
                    <span class="text-xs bg-brand-light text-brand-forest px-2 py-1 rounded-md font-medium">Mobile Order</span>
                    <span class="text-xs bg-brand-light text-brand-forest px-2 py-1 rounded-md font-medium">Seating</span>
                </div>
            </div>

            <div class="store-result p-4 border border-brand-forest/10 rounded-2xl mb-4 hover:border-brand-green hover:shadow-md transition-all cursor-pointer bg-white group">
                <h3 class="font-bold text-brand-forest mb-1">Westside Mall</h3>
                <p class="text-sm text-brand-forest/70 mb-1">789 West Blvd</p>
                <p class="text-xs text-brand-forest/50 mb-3">Open until 10:00 PM</p>
                <div class="flex gap-2">
                    <span class="text-xs bg-brand-light text-brand-forest px-2 py-1 rounded-md font-medium">Drive-Thru</span>
                </div>
            </div>
        </div>
    </div>

    <!-- Right Panel: Map View -->
    <div class="w-full md:w-2/3 lg:w-3/4 bg-gray-200 relative h-64 md:h-auto">
        <!-- Placeholder Map -->
        <div class="absolute inset-0 bg-[#E5E3DF]">
            <!-- Decorative Map Grid -->
            <div class="w-full h-full" style="background-image: linear-gradient(#d5d3cf 1px, transparent 1px), linear-gradient(90deg, #d5d3cf 1px, transparent 1px); background-size: 40px 40px;"></div>

            <!-- Map Pins Placeholder -->
            <div class="absolute top-1/3 left-1/3 transform -translate-x-1/2 -translate-y-1/2 text-brand-green hover:-translate-y-2 transition-transform cursor-pointer">
                <i data-lucide="map-pin" class="w-8 h-8 fill-brand-green text-white"></i>
            </div>
            <div class="absolute top-1/2 left-2/3 transform -translate-x-1/2 -translate-y-1/2 text-brand-green hover:-translate-y-2 transition-transform cursor-pointer">
                <i data-lucide="map-pin" class="w-8 h-8 fill-brand-green text-white"></i>
            </div>
            <div class="absolute top-2/3 left-1/2 transform -translate-x-1/2 -translate-y-1/2 text-brand-green hover:-translate-y-2 transition-transform cursor-pointer">
                <i data-lucide="map-pin" class="w-8 h-8 fill-brand-green text-white"></i>
            </div>
        </div>
    </div>
</main>

<script>
    // Toggle Order Type
    const btnPickup = document.getElementById('btn-pickup');
    const btnDelivery = document.getElementById('btn-delivery');

    btnPickup.addEventListener('click', () => {{
        btnPickup.classList.add('bg-white', 'shadow-sm', 'text-brand-forest');
        btnPickup.classList.remove('text-brand-forest/60');
        btnDelivery.classList.remove('bg-white', 'shadow-sm', 'text-brand-forest');
        btnDelivery.classList.add('text-brand-forest/60');
    }});

    btnDelivery.addEventListener('click', () => {{
        btnDelivery.classList.add('bg-white', 'shadow-sm', 'text-brand-forest');
        btnDelivery.classList.remove('text-brand-forest/60');
        btnPickup.classList.remove('bg-white', 'shadow-sm', 'text-brand-forest');
        btnPickup.classList.add('text-brand-forest/60');
    }});

    // Toggle Filter
    const btnFilter = document.getElementById('btn-filter');
    const filterPanel = document.getElementById('filter-panel');
    btnFilter.addEventListener('click', () => {{
        filterPanel.classList.toggle('hidden');
    }});

    // Search Input Mock
    const searchInput = document.getElementById('store-search');
    const searchMessage = document.getElementById('search-message');
    searchInput.addEventListener('input', (e) => {{
        if(e.target.value.length > 0) {{
            searchMessage.textContent = `Showing results for "${{e.target.value}}"`;
        }} else {{
            searchMessage.textContent = 'Zoom in to see stores in this area.';
        }}
    }});
</script>
</body>
</html>
"""

with open(os.path.join(output_dir, 'store-locator.html'), 'w') as f:
    f.write(page_content)
